'use strict';
window.AtlasVisuals=(()=>{
 const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const diagrams={
  solar:{label:'Sistema Solar',eyebrow:'ESPACIO',intro:'Las distancias son enormes y los tamaños no están a escala en este dibujo. Úsalo para ordenar, comparar y formular preguntas.',keys:['sun','mercury','venus','earth','mars','jupiter','saturn','uranus','neptune'],copy:{sun:['El Sol','Una estrella: concentra casi toda la masa del sistema solar y su gravedad mantiene a los planetas en órbita.'],mercury:['Mercurio','Es el planeta más cercano al Sol. Su año dura menos que el de cualquier otro planeta.'],venus:['Venus','Tiene una atmósfera muy densa y una temperatura superficial extrema.'],earth:['Tierra','Un planeta rocoso con agua líquida en la superficie y una atmósfera que permite la vida conocida.'],mars:['Marte','Un planeta rocoso con señales de agua pasada y una atmósfera mucho más delgada que la terrestre.'],jupiter:['Júpiter','El mayor planeta del sistema solar; es un gigante gaseoso.'],saturn:['Saturno','Gigante gaseoso rodeado por un sistema de anillos de hielo y roca.'],uranus:['Urano','Un gigante helado cuya inclinación hace que parezca girar de lado.'],neptune:['Neptuno','Un gigante helado muy lejano, con vientos extremadamente rápidos.']}},
  earth:{label:'Capas de la Tierra',eyebrow:'TIERRA',intro:'La Tierra no es una esfera de una sola pieza. Sus capas tienen materiales, temperaturas y funciones distintas.',keys:['crust','mantle','outer','inner'],copy:{crust:['Corteza','La capa sólida y delgada donde vivimos. Incluye corteza continental y oceánica.'],mantle:['Manto','Roca caliente que puede deformarse lentamente. Sus movimientos participan en la dinámica de las placas tectónicas.'],outer:['Núcleo externo','Capa metálica líquida. Sus movimientos ayudan a generar el campo magnético terrestre.'],inner:['Núcleo interno','Esfera metálica sólida sometida a presiones enormes y temperaturas muy altas.']}},
  water:{label:'Ciclo del agua',eyebrow:'TIERRA · AGUA',intro:'El agua cambia de lugar y de estado. El Sol aporta energía y la gravedad ayuda a que el agua vuelva a la superficie.',keys:['evaporation','condensation','precipitation','runoff'],copy:{evaporation:['Evaporación','El agua líquida recibe energía y pasa a la atmósfera como vapor. También las plantas aportan vapor mediante transpiración.'],condensation:['Condensación','El vapor se enfría y forma gotas o cristales alrededor de partículas de la atmósfera. Así aparecen las nubes.'],precipitation:['Precipitación','Cuando las gotas o cristales crecen, caen como lluvia, nieve o granizo según las condiciones.'],runoff:['Escurrimiento e infiltración','El agua puede correr hacia ríos y océanos o entrar al suelo y alimentar reservas subterráneas.']}},
  history:{label:'Historia como proceso',eyebrow:'HISTORIA',intro:'Una ruta histórica no es una fila de fechas aisladas. Observa cómo una situación cambia, quién participa y qué consecuencias quedan abiertas.',keys:['context','voices','change','questions'],copy:{context:['Contexto','Ubica el tiempo, el territorio, las instituciones y las condiciones que rodean un proceso.'],voices:['Voces y actores','Compara personas, comunidades y grupos con proyectos diferentes. Evita contar la historia como si una sola voz explicara todo.'],change:['Cambios y continuidades','Pregunta qué se transformó y qué permaneció. Las consecuencias suelen aparecer en distintos momentos y regiones.'],questions:['Preguntas y fuentes','Distingue hechos documentados, interpretaciones y tradiciones. Una buena pregunta conduce a una mejor fuente.']}}
 };
 let active='solar',selected='sun';
 function tabs(){return Object.entries(diagrams).map(([id,d])=>`<button data-visual-tab="${id}" aria-pressed="${active===id}">${safe(d.label)}</button>`).join('')}
 function solarSvg(){const planets=[['mercury',250,75,7],['venus',315,88,10],['earth',380,102,11],['mars',447,117,8],['jupiter',525,135,23],['saturn',620,157,19],['uranus',720,177,14],['neptune',810,195,14]];return `<svg class="atlas-diagram" viewBox="0 0 900 330" role="img" aria-label="Diagrama del sistema solar, no a escala"><defs><radialGradient id="sunGlow"><stop offset="0" stop-color="#ffe8a7"/><stop offset="1" stop-color="#de8c24"/></radialGradient></defs><rect width="900" height="330" rx="16" fill="#0d1b33"/><text x="22" y="30" fill="#b8e8ec" font-size="14" font-weight="700">DEL SOL HACIA AFUERA · NO A ESCALA</text><circle cx="92" cy="176" r="55" fill="url(#sunGlow)" data-visual-key="sun" tabindex="0"/><text x="92" y="258" text-anchor="middle" fill="#fff" font-size="14">Sol</text>${planets.map(([id,x,y,r])=>`<g data-visual-key="${id}" tabindex="0" role="button" aria-label="${diagrams.solar.copy[id][0]}"><ellipse cx="92" cy="176" rx="${x-92}" ry="${Math.max(18,(x-92)*.38)}" fill="none" stroke="#7b8ca5" stroke-opacity=".35"/><circle cx="${x}" cy="${y}" r="${r}" fill="${id==='earth'?'#5ca3c7':id==='mars'?'#bd6348':id==='jupiter'?'#c99f75':id==='saturn'?'#dfc38d':'#a8c4d5'}"/><text x="${x}" y="${y+35}" text-anchor="middle" fill="#fff" font-size="12">${diagrams.solar.copy[id][0]}</text></g>`).join('')}</svg>`}
 function earthSvg(){return `<svg class="atlas-diagram" viewBox="0 0 900 360" role="img" aria-label="Corte de las capas de la Tierra"><rect width="900" height="360" rx="16" fill="#0d1b33"/><text x="28" y="32" fill="#b8e8ec" font-size="14" font-weight="700">UN VIAJE HACIA EL CENTRO DE LA TIERRA</text><circle cx="250" cy="190" r="128" fill="#bc6a45" data-visual-key="crust" tabindex="0"/><circle cx="250" cy="190" r="98" fill="#d89057" data-visual-key="mantle" tabindex="0"/><circle cx="250" cy="190" r="62" fill="#d89a3e" data-visual-key="outer" tabindex="0"/><circle cx="250" cy="190" r="30" fill="#f5cf76" data-visual-key="inner" tabindex="0"/><path d="M390 76H520M350 120H520M315 170H520M282 222H520" stroke="#b8e8ec" stroke-width="2"/><text x="540" y="82" fill="#fff" font-size="16">Corteza</text><text x="540" y="126" fill="#fff" font-size="16">Manto</text><text x="540" y="176" fill="#fff" font-size="16">Núcleo externo</text><text x="540" y="228" fill="#fff" font-size="16">Núcleo interno</text><text x="28" y="326" fill="#c8d9ee" font-size="13">Las capas no tienen el mismo espesor en este esquema.</text></svg>`}
 function waterSvg(){return `<svg class="atlas-diagram" viewBox="0 0 900 360" role="img" aria-label="Diagrama del ciclo del agua"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#de8c24"/></marker></defs><rect width="900" height="360" rx="16" fill="#0d1b33"/><circle cx="110" cy="90" r="42" fill="#de8c24"/><g fill="#fff" opacity=".9"><ellipse cx="420" cy="92" rx="105" ry="33"/><ellipse cx="500" cy="100" rx="90" ry="27"/></g><path d="M190 124 C260 145 285 170 305 220" fill="none" stroke="#de8c24" stroke-width="4" marker-end="url(#arrow)" data-visual-key="evaporation" tabindex="0"/><path d="M520 130 C625 130 690 155 720 215" fill="none" stroke="#de8c24" stroke-width="4" marker-end="url(#arrow)" data-visual-key="precipitation" tabindex="0"/><path d="M725 270 C600 320 360 315 250 270" fill="none" stroke="#54b4c4" stroke-width="5" marker-end="url(#arrow)" data-visual-key="runoff" tabindex="0"/><path d="M420 55 C450 35 480 36 505 55" fill="none" stroke="#54b4c4" stroke-width="4" marker-end="url(#arrow)" data-visual-key="condensation" tabindex="0"/><text x="80" y="165" fill="#fff" font-size="15">Energía del Sol</text><text x="350" y="55" fill="#fff" font-size="15">Nubes</text><text x="665" y="250" fill="#fff" font-size="15">Lluvia</text><text x="350" y="344" fill="#fff" font-size="15">Ríos, suelo y océanos</text></svg>`}
 function historySvg(){const items=[['context','Contexto'],['voices','Voces'],['change','Cambios'],['questions','Preguntas']];return `<svg class="atlas-diagram" viewBox="0 0 900 260" role="img" aria-label="Mapa de lectura de un proceso histórico"><rect width="900" height="260" rx="16" fill="#2a1d22"/><text x="28" y="35" fill="#f7d8af" font-size="14" font-weight="700">UNA HISTORIA SE INVESTIGA EN VARIAS CAPAS</text>${items.map(([id,label],i)=>{const x=105+i*220;return `<g data-visual-key="${id}" tabindex="0" role="button" aria-label="${label}"><circle cx="${x}" cy="135" r="48" fill="${['#c47b54','#d7a24d','#6ea9a3','#b8e8ec'][i]}"/><text x="${x}" y="141" text-anchor="middle" fill="#17263b" font-size="15" font-weight="700">${label}</text>${i<3?`<path d="M${x+55} 135H${x+160}" stroke="#f7d8af" stroke-width="3" marker-end="url(#arrow)"/>`:''}</g>`}).join('')}<text x="28" y="226" fill="#f6eadb" font-size="13">Haz clic en cada capa y después vuelve a la ruta histórica.</text></svg>`}
 function diagram(){return active==='solar'?solarSvg():active==='earth'?earthSvg():active==='water'?waterSvg():historySvg()}
 function render(){const host=q('#visualsApp');if(!host)return;const d=diagrams[active],info=d.copy[selected]||d.copy[d.keys[0]];host.innerHTML=`<div class="visual-shell"><nav class="visual-tabs" aria-label="Biblioteca de gráficas">${tabs()}</nav><div class="visual-layout"><div><div class="visual-intro"><span class="science-label">${safe(d.eyebrow)}</span><h2>${safe(d.label)}</h2><p>${safe(d.intro)}</p></div><div class="visual-stage">${diagram()}</div><p class="visual-credit">Dibujo educativo vectorial creado para Atlas · No sustituye la escala real ni una fuente primaria.</p></div><aside class="visual-explain"><span class="science-label">EXPLICACIÓN ACTUAL</span><h2>${safe(info[0])}</h2><p>${safe(info[1])}</p><div class="visual-question"><strong>Pregunta para pensar</strong><p>${active==='history'?'¿Qué fuente necesitarías para comprobar esta idea?':active==='water'?'¿Qué cambiaría si el Sol aportara menos energía?':active==='earth'?'¿Qué señales veríamos en la superficie si una capa interna cambiara?':'¿Qué comparación te ayuda a recordar este concepto?'}</p></div><a class="atlas-outline" href="${active==='history'?'#temas':active==='water'?'#ciencia/ciclo-del-agua':active==='earth'?'#ciencia/interior-tierra':'#laboratorio/planetas'}">Continuar la exploración →</a></aside></div></div>`;bind();}
 function bind(){all('[data-visual-tab]').forEach(b=>b.onclick=()=>{active=b.dataset.visualTab;selected=diagrams[active].keys[0];render()});all('[data-visual-key]').forEach(el=>{el.onclick=()=>{selected=el.dataset.visualKey;render()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=el.dataset.visualKey;render()}}});}
 function init(){render()}
 function route(hash){if(hash==='visuales')render()}
 return {init,route};
})();
